(() => {
  'use strict';
  const el=id=>document.getElementById(id),money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(Number(n)||0);
  let orders=[];
  async function api(path){const response=await fetch('../../../api/vendor/'+path,{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}});const data=await response.json().catch(()=>({}));if(!response.ok||!data.success)throw Error(data.message||'Report request failed.');return data;}
  function cell(row,value){const td=document.createElement('td');td.textContent=String(value??'—');row.append(td);return td;}
  function info(container,items,empty){container.replaceChildren();if(!items.length){container.textContent=empty;return;}items.forEach(([label,value])=>{const row=document.createElement('div');row.className='vc-info-row';const first=document.createElement('span');first.textContent=label.replaceAll('_',' ');const second=document.createElement('strong');second.textContent=String(value);row.append(first,second);container.append(row);});}
  async function load(){try{const [orderData,productData,returnData]=await Promise.all([api('orders.php'),api('products.php'),api('returns.php')]);orders=orderData.orders||[];const products=productData.products||[],returns=returnData.returns||[];const total=orders.reduce((sum,o)=>sum+Number(o.total_amount||0),0);el('va-sales').textContent=money(total);el('va-orders').textContent=String(orders.length);el('va-average').textContent=money(orders.length?total/orders.length:0);el('va-returns').textContent=String(returns.length);const count=items=>Object.entries(items.reduce((map,item)=>{const key=item.status||'unknown';map[key]=(map[key]||0)+1;return map;},{})).sort((a,b)=>b[1]-a[1]);info(el('va-statuses'),count(orders),'No orders recorded yet.');info(el('va-products'),count(products),'No products created yet.');const body=el('va-rows');body.replaceChildren();if(!orders.length){cell(body.appendChild(document.createElement('tr')),'No orders yet.').colSpan=5;}else orders.slice(0,20).forEach(o=>{const row=document.createElement('tr');cell(row,o.group_number);cell(row,o.created_at);cell(row,o.status.replaceAll('_',' '));cell(row,o.unit_count);cell(row,money(o.total_amount));body.append(row);});el('va-status').textContent=orders.length+' recorded orders · '+products.length+' products';}catch(error){el('va-status').textContent=error.message;el('va-status').className='vc-status warning';}}
  el('va-export').addEventListener('click',()=>{const quote=value=>'"'+String(value??'').replaceAll('"','""')+'"';const lines=[['Order','Date','Status','Items','Subtotal','Shipping','Tax','Total','Payment'].join(',')];orders.forEach(o=>lines.push([o.group_number,o.created_at,o.status,o.unit_count,o.subtotal,o.shipping_amount,o.tax_amount,o.total_amount,o.payment_status].map(quote).join(',')));const url=URL.createObjectURL(new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='vendor-orders-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
  load();
})();
